The modulus operator `%` returns the remainder of the division between two operands. For example, `5 % 2` will return `1`, because `5 ÷ 2` gives `2 with a remainder of 1`. 

In this context, when we are checking whether a given number is a prime, we need to determine if it's divisible by any integer except itself and 1. 

Here's how that works within our function:

``` javascript
function checkPrime(arr) {
  arr.forEach(num => { // Loop through each number in the provided array
    let isPrime = true; // Assuming every number passed preliminary check

    // Check if num is less than or equal to 1 (which aren't prime numbers)
    if (num <= 1) {
      isPrime = false;
    } else {
      for (let I = 2; I < num; i++) { // Loop through every possible factor of num (excluding 1 & itself)
        if (num % I === 0) { // As soon as we find a factor, num isn't prime anymore
          isPrime = false;
          break; // Early exit - no point in continuing the search
        }
      }
    }

    // Printing the prime number(s) found (if any)
    if (isPrime) {
      console.log(num);
    }
  });
}
